 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2}
    diamonds = []
    while cells:
        start = cells.pop()
        comp = {start}
        stack = [start]
        while stack:
            r, c = stack.pop()
            for dr in (-1, 1):
                for dc in (-1, 1):
                    p = (r + dr, c + dc)
                    if p in cells:
                        cells.remove(p)
                        comp.add(p)
                        stack.append(p)
        rs = [r for r, c in comp]
        cs = [c for r, c in comp]
        diamonds.append((min(rs), max(rs), min(cs), max(cs)))

    # Join diamond tips when their centers share a row or column.
    for i, a in enumerate(diamonds):
        ar0, ar1, ac0, ac1 = a
        acr, acc = (ar0 + ar1) / 2, (ac0 + ac1) / 2
        for b in diamonds[i + 1:]:
            br0, br1, bc0, bc1 = b
            bcr, bcc = (br0 + br1) / 2, (bc0 + bc1) / 2
            if acr == bcr:
                row = int(acr)
                lo, hi = sorted((acc, bcc))
                left, right = (a, b) if acc < bcc else (b, a)
                start_col = int((left[2] + left[3]) / 2) + 1
                end_col = int((right[2] + right[3]) / 2)
                for c in range(start_col, end_col):
                    if grid[row][c] == 0:
                        out[row][c] = 1
            elif acc == bcc:
                col = int(acc)
                top, bottom = (a, b) if acr < bcr else (b, a)
                start_row = int((top[0] + top[1]) / 2) + 1
                end_row = int((bottom[0] + bottom[1]) / 2)
                for r in range(start_row, end_row):
                    if grid[r][col] == 0:
                        out[r][col] = 1
    return out
